SELECT COUNT(*)
FROM user_events
WHERE created_at BETWEEN #{from} AND #{to}

SELECT event_type as eventType, COUNT(*) as count
FROM user_events
WHERE user_id = #{userId}
  AND created_at BETWEEN #{from} AND #{to}
GROUP BY event_type

SELECT user_id as userId, MAX(created_at) as lastActiveAt FROM user_events WHERE user_id IN
#{userId}
GROUP BY user_id
